let bakeryTurn5=null;
const foodRound5=n=>Math.round(n*1000000)/1000000;
function defaultFood5(){return {enabled:false,source:'external',budget:18000,reserve:2,plan:{pastry:{recipe:'food-croissant',qty:35},sandwich:{recipe:'food-sandwich',qty:20}},lots:[],last:null,history:[]};}
function ensureBakery5(v){if(v.bakery5===undefined)v.bakery5={recipes:Object.entries(FOOD_BASES5).map(([id,b])=>({id:'food-'+id,name:b.name,base:id,richness:100,version:1})),bakeries:[],history:[]};if(Array.isArray(v.stores))for(const s of v.stores)if(s.food5===undefined)s.food5=defaultFood5();return v;}
