function saveFoodRecipe5(id,data){guard();if(!data||typeof data.name!=='string'||!data.name.trim()||data.name.length>50||!Object.hasOwn(FOOD_BASES5,data.base)||!Number.isInteger(data.richness)||data.richness<70||data.richness>140)throw Error('Vyplň název, základ receptury a bohatost 70–140 %.');const r=state.bakery5.recipes.find(r=>r.id===id);if(id&&!r||!r&&state.bakery5.recipes.length>=30)throw Error('Recepturu nelze uložit.');if(r&&FOOD_BASES5[r.base].category!==FOOD_BASES5[data.base].category&&state.stores.some(s=>Object.values(s.food5.plan).some(p=>p.recipe===id)))throw Error('Používaná receptura musí zachovat kategorii. Vytvoř novou.');if(r)Object.assign(r,{name:data.name.trim(),base:data.base,richness:data.richness,version:r.version+1});else state.bakery5.recipes.push({id:uid('food'),base:data.base,richness:data.richness,name:data.name.trim(),version:1});}
