function buyBakery5(type,city){guard();if(!Object.hasOwn(BAKERY_TYPES5,type)||!CITIES.some(c=>c.name===city)||!state.stores.some(s=>loc(s.id).city===city&&!s.franchise)||state.bakery5.bakeries.length>=8)throw Error('Pekárna potřebuje město s vlastní kavárnou; nejvýše osm pekáren.');const t=BAKERY_TYPES5[type];if(state.founderShare<50&&state.expansionBudget<t.cost)throw Error('Pekárna potřebuje expanzní mandát boardu.');spend(t.cost);if(state.founderShare<50)state.expansionBudget-=t.cost;const b={id:uid('bakery'),name:t.name+' · '+city,type,city,cost:t.cost,staff:t.staff,wage:6500,shifts:1,condition:100,manager:null,auto:true,budget:35000,reserve:2,raw:[],last:null,history:[],maintenance:false};state.bakery5.bakeries.push(b);log('Vlastní pekárna v '+city,money(t.cost)+'. Nastav odběr jídla v kavárnách.');return b;}
function setBakery5(id,data){guard();const b=bakeryById5(id);if(!b||!data||!Number.isInteger(data.staff)||data.staff<1||data.staff>15||![1,2,3].includes(data.shifts)||typeof data.auto!=='boolean'||typeof data.maintenance!=='boolean'||!Number.isInteger(data.budget)||data.budget<0||data.budget>200000||!Number.isInteger(data.reserve)||data.reserve<1||data.reserve>8)throw Error('Neplatný tým, směny nebo mandát pekárny.');const hire=typeof bakeryHireFee6==='function'?bakeryHireFee6(b,data):Math.max(0,data.staff-b.staff)*8000;spend(hire);Object.assign(b,Object.fromEntries(['staff','shifts','auto','maintenance','budget','reserve'].map(k=>[k,data[k]])));}
function serviceBakery5(id){guard();const b=bakeryById5(id);if(!b)throw Error('Pekárna neexistuje.');spend(b.cost*.04);b.condition=100;state.pendingExpense3=(state.pendingExpense3||0)+b.cost*.04;}
function setFoodPlan5(id,data){guard();const s=state.stores.find(s=>s.id===id&&!s.franchise);if(!s||!data||typeof data.enabled!=='boolean'||data.source!=='external'&&!bakeryById5(data.source)||!Number.isInteger(data.budget)||data.budget<0||data.budget>100000||!Number.isInteger(data.reserve)||data.reserve<1||data.reserve>8)throw Error('Neplatný odběr nebo rozpočet jídla.');for(const cat of ['pastry','sandwich']){const p=data.plan?.[cat];if(!p||!Number.isInteger(p.qty)||p.qty<0||p.qty>500||foodRecipe5(p.recipe).category!==cat)throw Error('Vyber správnou recepturu a 0–500 kusů denně.');}s.food5={...s.food5,...Object.fromEntries(['enabled','source','budget','reserve','plan'].map(k=>[k,JSON.parse(JSON.stringify(data[k]))]))};}
function foodRate5(s,cat,r){return (cat==='pastry'?.22:.14)*clamp(1+(r.quality-75)/180-(s.menu[cat].price-(cat==='pastry'?65:106))/170,.25,1.5);}
