companyValue=function(){return BAKERY_BASE5.companyValue()+state.bakery5.bakeries.reduce((n,b)=>n+b.cost*b.condition/100+b.raw.reduce((a,l)=>a+l.kg*l.cost,0),0)+state.stores.reduce((n,s)=>n+s.food5.lots.reduce((a,l)=>a+l.qty*l.cost,0),0);};
