menuSummary=function(s){const m=BAKERY_BASE5.menuSummary(s);if(!s.food5?.enabled||s.franchise)return m;const oldMinutes=m.food.reduce((n,f)=>n+f.rate*f.minutes,0);m.food=m.food.map(f=>{const r=foodRecipe5(s.food5.plan[f.id].recipe);return {...f,recipe:r.id,rate:foodRate5(s,f.id,r),minutes:r.minutes};});return {...m,minutes:m.minutes-oldMinutes+m.food.reduce((n,f)=>n+f.rate*f.minutes,0),foodRevenue:0,foodCost:0};};
function rawFoodQuote5(id,ingredient,kg){const b=bakeryById5(id);if(!b||!Object.hasOwn(INGREDIENTS5,ingredient)||!Number.isFinite(kg)||kg<.1||kg>500)throw Error('Zvol surovinu a množství 0,1–500 kg.');return {cost:foodRound5(kg*INGREDIENTS5[ingredient].price),kg,ingredient};}
function buyFoodRaw5(id,ingredient,kg){guard();const q=rawFoodQuote5(id,ingredient,kg),b=bakeryById5(id);if(b.raw.length>=200)throw Error('Sklad má příliš mnoho otevřených partií.');spend(q.cost);const day=(state.week-1)*7;b.raw.push({id:uid('rawfood'),ingredient,kg:foodRound5(kg),cost:INGREDIENTS5[ingredient].price,arrived:day,expires:day+INGREDIENTS5[ingredient].life});return q;}
function foodBudgetPay5(owner,amount){const ledger=bakeryTurn5.budgets,spent=ledger[owner.id]||0;if(!Number.isFinite(amount)||amount<0||spent+amount>owner.budget+.000001||state.cash-amount<weeklyFixed()*owner.reserve)return false;state.cash-=amount;ledger[owner.id]=spent+amount;bakeryTurn5.purchases+=amount;return true;}
function expireFoodRaw5(b,day){for(const l of b.raw)if(l.expires<=day){const loss=l.kg*l.cost;b.last.waste+=loss;bakeryTurn5.waste+=loss;l.kg=0;}b.raw=b.raw.filter(l=>l.kg>.000001);}
function rawFoodAvailable5(b,k,day){return b.raw.filter(l=>l.ingredient===k&&l.expires>day&&l.arrived<=day).reduce((n,l)=>n+l.kg,0);}
function foodLot5(r,qty,cost,source,made,arrival,quality=r.quality){return {id:uid('foodlot'),recipe:r.id,version:r.version,name:r.name,category:r.category,qty,cost:foodRound5(cost),source,made,arrival,expires:made+r.life,quality};}
function bakeryProduce5(b,r,want,day){const limit=Math.floor(b.last.dayCapacity/r.work),requested=Math.min(want,limit);if(!requested)return null;const missing=Object.entries(r.ingredients).map(([k,q])=>({k,kg:Math.max(0,q*requested-rawFoodAvailable5(b,k,day))})).filter(x=>x.kg>.000001),cost=missing.reduce((n,x)=>n+x.kg*INGREDIENTS5[x.k].price,0);if(b.auto&&cost&&b.raw.length+missing.length<=200&&foodBudgetPay5(b,cost))for(const x of missing)b.raw.push({id:uid('rawfood'),ingredient:x.k,kg:foodRound5(x.kg),cost:INGREDIENTS5[x.k].price,arrived:day,expires:day+INGREDIENTS5[x.k].life});const qty=Math.min(requested,...Object.entries(r.ingredients).map(([k,q])=>Math.floor((rawFoodAvailable5(b,k,day)+.000001)/q)));if(!qty||!foodBudgetPay5(b,qty*(typeof foodEnergyUnit8==='function'?foodEnergyUnit8(r):2.2)))return null;let consumed=qty*(typeof foodEnergyUnit8==='function'?foodEnergyUnit8(r):2.2);for(const [k,q] of Object.entries(r.ingredients)){let left=q*qty;for(const l of b.raw.filter(l=>l.ingredient===k&&l.arrived<=day&&l.expires>day).sort((a,b)=>a.expires-b.expires)){const n=Math.min(left,l.kg);l.kg=foodRound5(l.kg-n);left-=n;consumed+=n*l.cost;if(left<.000001)break;}}b.raw=b.raw.filter(l=>l.kg>.000001);b.last.produced+=qty;b.last.work+=qty*r.work;b.last.dayCapacity-=qty*r.work;return foodLot5(r,qty,consumed/qty,b.id,day,day,clamp(r.quality+(b.manager?.strength.product||0)/25-(100-b.condition)*.08,25,99));}
function prepareBakeryWeek5(){if(!bakeryTurn5)return;const start=(state.week-1)*7;for(const b of state.bakery5.bakeries){b.condition=clamp(b.condition-.8*b.shifts,25,100);b.last={week:state.week,produced:0,delivered:0,sold:0,revenue:0,cogs:0,waste:0,wasted:0,operating:bakeryFixed5(b),work:0,capacity:bakeryCapacity5(b)*6,utilization:0,profit:0,days:[],owner:b.manager?.name||'Zakladatel'};if(b.maintenance&&b.condition<75&&foodBudgetPay5(b,b.cost*.04)){b.condition=100;b.last.operating+=b.cost*.04;bakeryTurn5.prepaidOperating+=b.cost*.04;}b.last.capacity=bakeryCapacity5(b)*6;}
 for(let d=0;d<6;d++){const day=start+d;for(const b of state.bakery5.bakeries){expireFoodRaw5(b,day);b.last.dayCapacity=bakeryCapacity5(b);const produced=b.last.produced,delivered=b.last.delivered;if(typeof prepareFoodTradeDay9==='function')prepareFoodTradeDay9(b,day,'before');for(const s of (typeof foodPriority7==='function'?foodPriority7(b):state.stores.filter(s=>s.food5.enabled&&!s.franchise&&s.food5.source===b.id)))for(const cat of ['pastry','sandwich']){const p=typeof foodProductionPlan7==='function'?foodProductionPlan7(s,cat,day,b):s.food5.plan[cat];if((typeof foodCanProduce8==='function'&&!foodCanProduce8(s,p.recipe))||!p.qty||!s.menu[cat].enabled||!s.equipment[MENU[cat].requires])continue;const r=foodRecipe5(p.recipe),route=foodRoute5(b,s,r);if(route.days>=r.life)continue;const lot=bakeryProduce5(b,r,typeof foodTradeAffordable9==='function'&&route.maxUnits!==undefined?foodTradeAffordable9(b,r,p.qty,day,route):Math.min(p.qty,route.maxUnits??p.qty),day);if(!lot)continue;if(!foodBudgetPay5(b,typeof foodDeliveryCost9==='function'?foodDeliveryCost9(route,lot.qty):lot.qty*route.cost)){b.last.waste+=lot.qty*lot.cost;b.last.wasted+=lot.qty;bakeryTurn5.waste+=lot.qty*lot.cost;continue;}lot.cost=foodRound5(lot.cost+(typeof foodDeliveryCost9==='function'?foodDeliveryCost9(route,lot.qty)/lot.qty:route.cost));lot.arrival+=route.days;s.food5.lots.push(lot);if(typeof recordFoodDelivery7==='function')recordFoodDelivery7(s,cat,lot,day);if(typeof recordFoodDelivery9==='function')recordFoodDelivery9(s,cat,lot,day,route);b.last.delivered+=lot.qty;}if(typeof prepareFoodTradeDay9==='function')prepareFoodTradeDay9(b,day,'after');b.last.days.push({day:d,produced:b.last.produced-produced,delivered:b.last.delivered-delivered});delete b.last.dayCapacity;}
 for(const s of state.stores.filter(s=>s.food5.enabled&&!s.franchise&&s.food5.source==='external'))for(const cat of ['pastry','sandwich']){const p=typeof foodProductionPlan7==='function'?foodProductionPlan7(s,cat,day,null):s.food5.plan[cat];if((typeof foodCanProduce8==='function'&&!foodCanProduce8(s,p.recipe))||!p.qty||!s.menu[cat].enabled||!s.equipment[MENU[cat].requires])continue;const r=foodRecipe5(p.recipe),cost=r.unitCost*1.6+3;if(foodBudgetPay5({...s.food5,id:s.id},cost*p.qty))s.food5.lots.push(foodLot5(r,p.qty,cost,'external',day,day));}}
}
processShipments=function(){const r=BAKERY_BASE5.processShipments();prepareBakeryWeek5();return r;};
function expireCafeFood5(s,day,result){for(const l of s.food5.lots)if(l.expires<=day){const cost=l.qty*l.cost;result.waste+=cost;result.wasted+=l.qty;bakeryTurn5.waste+=cost;const b=bakeryById5(l.source);if(b){b.last.waste+=cost;b.last.wasted+=l.qty;}l.qty=0;}s.food5.lots=s.food5.lots.filter(l=>l.qty>0);}
function settleBakeryFood5(s,served,demand){if(!bakeryTurn5||s.franchise)return null;const f=s.food5,result={week:state.week,enabled:f.enabled,sold:0,lost:0,revenue:0,cost:0,waste:0,wasted:0,days:[],items:[],source:f.source};let cumulative=0,previous=0;const pending=s.daily.pending;for(let day=0;day<6;day++){const absolute=(state.week-1)*7+day;expireCafeFood5(s,absolute,result);const potential=pending?.days[day]?.timeline.reduce((n,p)=>n+p.served,0)??demand.potential/6;cumulative+=potential;const now=demand.potential?Math.round(served*cumulative/demand.potential):0,count=now-previous;previous=now;const row={day,served:count,sold:0,lost:0,revenue:0,cost:0};if(f.enabled)for(const cat of ['pastry','sandwich']){if(!s.menu[cat].enabled||!s.equipment[MENU[cat].requires])continue;const r=foodRecipe5(f.plan[cat].recipe);if(typeof foodCanSell8==='function'&&!foodCanSell8(s,r.id))continue;const fresh=f.lots.filter(l=>l.recipe===r.id&&l.arrival<=absolute&&l.expires>absolute),available=fresh.reduce((n,l)=>n+l.qty,0),quality=available?fresh.reduce((n,l)=>n+l.qty*l.quality,0)/available:r.quality,wanted=typeof foodWanted8==='function'?foodWanted8(s,cat,r,count,day,demand,quality):Math.round(count*foodRate5(s,cat,{...r,quality}));let left=wanted,qty=0,cost=0;for(const l of fresh.sort((a,b)=>a.expires-b.expires||a.made-b.made)){const n=Math.min(left,l.qty,typeof foodLotSaleLimit9==='function'?foodLotSaleLimit9(s,l,day,wanted,qty):left);l.qty-=n;left-=n;qty+=n;cost+=n*l.cost;if(typeof foodSoldUnits8==='function')foodSoldUnits8(s,cat,day,l.source,n);const b=bakeryById5(l.source);if(b){b.last.sold+=n;b.last.revenue+=n*s.menu[cat].price;b.last.cogs+=n*l.cost;}if(!left)break;}const pricing=typeof foodSale8==='function'?foodSale8(s,cat,r,qty,count,day):{revenue:qty*s.menu[cat].price},revenue=pricing.revenue;if(typeof foodSaleLedger8==='function')foodSaleLedger8(s,cat,r,qty,day,pricing);result.items.push({day,category:cat,recipe:r.id,name:r.name,qty,wanted,revenue,cost,...(pricing.combo8!==undefined?{combo8:pricing.combo8,comboDiscount8:pricing.discount8}: {})});row.sold+=qty;row.lost+=left;row.revenue+=revenue;row.cost+=cost;}if(typeof rescueFoodDay7==='function')rescueFoodDay7(s,absolute,row,result,count);result.days.push(row);result.sold+=row.sold;result.lost+=row.lost;result.revenue+=row.revenue;result.cost+=row.cost;}
 expireCafeFood5(s,(state.week-1)*7+6,result);f.lots=f.lots.filter(l=>l.qty>0);f.last=result;f.history.push(JSON.parse(JSON.stringify(result)));f.history=f.history.slice(-26);bakeryTurn5.consumed+=result.cost;return f.enabled?result:null;}
function bakeryCompanyLedger5(){if(bakeryTurn5)for(const b of state.bakery5.bakeries)expireFoodRaw5(b,(state.week-1)*7+6);return bakeryTurn5?{operating:state.bakery5.bakeries.reduce((n,b)=>n+b.last.operating,0),waste:bakeryTurn5.waste,consumed:bakeryTurn5.consumed+bakeryTurn5.prepaidOperating,purchases:bakeryTurn5.purchases}:{operating:0,waste:0,consumed:0,purchases:0};}
recordMenuSales=function(s){BAKERY_BASE5.recordMenuSales(s);if(s.food5.enabled&&s.food5.last){s.lastItems=s.lastItems.filter(x=>!MENU[x.id].food);for(const cat of ['pastry','sandwich']){const items=s.food5.last.items.filter(i=>i.category===cat);s.lastItems.push({id:cat,count:items.reduce((n,i)=>n+i.qty,0),revenue:items.reduce((n,i)=>n+i.revenue,0),minutes:foodRecipe5(s.food5.plan[cat].recipe).minutes});}}};
finalizeService5=function(s){BAKERY_BASE5.finalizeService5(s);if(!s.food5.enabled||!s.food5.last||!s.daily.last)return;for(const day of s.daily.last.days){const f=s.food5.last.days[day.day]||s.food5.last.days[s.daily.last.days.indexOf(day)];let count=0,prev=0;for(const p of day.timeline){count+=p.served;const now=day.served?f.revenue*count/day.served:0;p.revenue=p.served*s.menuStats.price+now-prev;prev=now;}day.revenue=day.timeline.reduce((n,p)=>n+p.revenue,0);}};
